insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-001', 'N5', 'blank', null, 'きのうは 日曜日でした。わたしは 友だちの うち（１）行きました。友だちの うちは 駅から とおいです（２）、バスで 行きました。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-002', 'N5', 'blank', null, '田中さんへ
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-003', 'N5', 'essay', null, '山田さんは 日曜日に 友だちと 買い物に 行きます。デパートで くつを 買います。それから、レストランで ごはんを 食べます。', 'original', 'approved') on conflict (id) do update set level = excluded.level, genre = excluded.genre, title = excluded.title, body = excluded.body, status = excluded.status;
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-004', 'N5', 'email', null, 'ワンさんへ
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-005', 'N5', 'life', null, 'ゆうこさんは 毎朝 六時に 起きます。それから 犬と 公園を 走ります。うちに 帰って、シャワーを あびて、朝ごはんを 食べます。', 'original', 'approved') on conflict (id) do update set level = excluded.level, genre = excluded.genre, title = excluded.title, body = excluded.body, status = excluded.status;
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-006', 'N5', 'notice', null, '【お知らせ】
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-007', 'N5', 'life', null, 'わたしの しゅみは 料理です。毎週 土曜日に 友だちを うちに よんで、いっしょに ごはんを 食べます。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-008', 'N5', 'life', null, 'リサさんは 先月 日本に 来ました。日本語学校で 毎日 勉強して います。学校は うちから 電車で 三十分 かかります。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-009', 'N5', 'info', null, '【プールの ごあんない】
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n5-ps-010', 'N5', 'info', null, '【ひまわり 書店】
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-001', 'N4', 'blank', null, 'わたしは 先月 東京から 大阪へ 引っ越しました。引っ越す 前は、新しい 町で 友だちが できるか 心配でした。（１）、大阪の 人は とても 親切です。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-002', 'N4', 'blank', null, '最近、運動不足だと 思って、会社へ 歩いて 行く ことに しました。家から 会社まで 四十分 かかります。（１）、毎朝 六時に 起きなければ なりません。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-003', 'N4', 'email', null, 'たなかさん
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-004', 'N4', 'notice', null, '【お願い】
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-005', 'N4', 'life', null, 'わたしは 毎週 日曜日に 図書館で 本を 借ります。先週は 料理の 本を 三冊 借りました。でも、まだ 一冊しか 読んで いません。来週 返す までに ぜんぶ 読みたいです。', 'original', 'approved') on conflict (id) do update set level = excluded.level, genre = excluded.genre, title = excluded.title, body = excluded.body, status = excluded.status;
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-006', 'N4', 'notice', null, 'メモ
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-007', 'N4', 'email', null, 'たかはしさん
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-008', 'N4', 'life', null, 'わたしの うちから 駅までは 歩いて 二十分 かかります。バスも ありますが、本数が 少なくて、一時間に 二本しか 来ません。それで、去年 自転車を 買いました。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-009', 'N4', 'life', null, 'ケンさんは 日本語学校の 学生です。毎日 授業の あと、図書館で 一時間 復習して います。先生は 「復習は その 日の うちに した ほうが いい」と 言いました。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-010', 'N4', 'life', null, '駅の 近くの スーパーでは、毎週 火曜日に 野菜が 安く なります。わたしは いつも 火曜日の 夕方に 買い物に 行きます。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-011', 'N4', 'life', null, 'わたしは 毎朝 コーヒーを 飲みます。以前は 砂糖を 入れて いましたが、健康の ために、去年から 入れない ことに しました。
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-012', 'N4', 'info', null, '【こども 料理教室 ごあんない】
insert into public.reading_passages (id, level, genre, title, body, source, status) values ('n4-ps-013', 'N4', 'info', null, '【駅前 レンタサイクル】
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-001', 'N5', 'vocabulary', 'kanji_reading', 1, '[[学校]]に 行きます。', null, '["がくこう","がっこう","かっこう","がっこ"]'::jsonb, 1, '「学校」讀作「がっこう」（學校）。「学」單獨是「がく」，但在「学校」中「く」與「こ」相連而促音化為「がっ」。', null, '[{"word":"学校","reading":"がっこう","meaning":"學校"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-002', 'N5', 'vocabulary', 'kanji_reading', 1, '[[毎日]] 日本語を 勉強します。', null, '["まいにち","めいにち","まいじつ","まいひ"]'::jsonb, 0, '「毎日」讀作「まいにち」，意思是「每天」。「毎」是「まい」，「日」在這裡讀「にち」。', null, '[{"word":"毎日","reading":"まいにち","meaning":"每天"},{"word":"勉強","reading":"べんきょう","meaning":"讀書、學習"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-003', 'N5', 'vocabulary', 'kanji_reading', 1, '先生は [[来週]] 大阪へ 行きます。', null, '["らいじゅう","らいしゅ","らいしゅう","らんしゅう"]'::jsonb, 2, '「来週」讀作「らいしゅう」（下週）。「週」讀「しゅう」，不要唸成「じゅう」。', null, '[{"word":"来週","reading":"らいしゅう","meaning":"下週"},{"word":"今週","reading":"こんしゅう","meaning":"這週"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-004', 'N5', 'vocabulary', 'kanji_reading', 1, '[[友だち]]と 映画を 見ました。', null, '["ゆうだち","ともたち","とうだち","ともだち"]'::jsonb, 3, '「友だち」讀作「ともだち」（朋友）。「友」的訓讀是「とも」，後面的「だち」要濁音。', null, '[{"word":"友だち","reading":"ともだち","meaning":"朋友"},{"word":"映画","reading":"えいが","meaning":"電影"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-005', 'N5', 'vocabulary', 'kanji_reading', 1, 'いま、[[時間]]が ありません。', null, '["しかん","じかん","じげん","じっかん"]'::jsonb, 1, '「時間」讀作「じかん」（時間）。', null, '[{"word":"時間","reading":"じかん","meaning":"時間"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-006', 'N5', 'vocabulary', 'kanji_reading', 1, '母は [[料理]]が 上手です。', null, '["りょり","ろうり","りょうり","りょうい"]'::jsonb, 2, '「料理」讀作「りょうり」（料理、做菜）。注意「りょう」是長音。', null, '[{"word":"料理","reading":"りょうり","meaning":"料理、做菜"},{"word":"上手","reading":"じょうず","meaning":"擅長"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-007', 'N5', 'vocabulary', 'kanji_reading', 1, '毎朝 [[九時]]に 学校へ 行きます。', null, '["きゅうじ","くじ","ここのじ","きゅじ"]'::jsonb, 1, '「九時」是特殊讀法，讀作「くじ」（九點）。時間的「九」不唸「きゅう」。同樣要注意「四時（よじ）」「七時（しちじ）」。', null, '[{"word":"九時","reading":"くじ","meaning":"九點"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-008', 'N5', 'vocabulary', 'kanji_reading', 1, '[[水曜日]]に テストが あります。', null, '["みずようび","すいようひ","すいようび","すいよび"]'::jsonb, 2, '「水曜日」讀作「すいようび」（星期三）。星期的「水」用音讀「すい」。', null, '[{"word":"水曜日","reading":"すいようび","meaning":"星期三"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-kr-009', 'N5', 'vocabulary', 'kanji_reading', 1, '[[外国]]の 友だちが 来ます。', null, '["がいこく","げこく","がいごく","がいくに"]'::jsonb, 0, '「外国」讀作「がいこく」（外國）。「外」的音讀是「がい」。', null, '[{"word":"外国","reading":"がいこく","meaning":"外國"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-or-001', 'N5', 'vocabulary', 'orthography', 1, 'あしたは [[やすみ]]です。', null, '["体み","休み","木み","作み"]'::jsonb, 1, '「やすみ」寫作「休み」（休息、假日）。「休」是人（亻）靠在樹（木）旁邊；「体」讀作「からだ／たい」。', null, '[{"word":"休み","reading":"やすみ","meaning":"休息、假日"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-or-002', 'N5', 'vocabulary', 'orthography', 1, '毎日 [[でんしゃ]]で 会社へ 行きます。', null, '["電東","雷車","電車","電軍"]'::jsonb, 2, '「でんしゃ」寫作「電車」（電車）。注意「電」與「雷」的下半部不同。', null, '[{"word":"電車","reading":"でんしゃ","meaning":"電車"},{"word":"会社","reading":"かいしゃ","meaning":"公司"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-or-003', 'N5', 'vocabulary', 'orthography', 1, 'この 道は [[ながい]]です。', null, '["長い","張い","帳い","表い"]'::jsonb, 0, '「ながい」寫作「長い」（長的）。其他選項的字形雖然相似，但不是「ながい」。', null, '[{"word":"長い","reading":"ながい","meaning":"長的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-or-004', 'N5', 'vocabulary', 'orthography', 1, '[[かめら]]で 写真を とります。', null, '["カナラ","ガメラ","カメラ","カヌラ"]'::jsonb, 2, '外來語「かめら」用片假名寫成「カメラ」（相機）。「メ」容易與「ナ」「ヌ」混淆，要小心。', null, '[{"word":"カメラ","reading":"かめら","meaning":"相機"},{"word":"写真","reading":"しゃしん","meaning":"照片"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-or-005', 'N5', 'vocabulary', 'orthography', 1, '駅で [[ともだち]]に 会いました。', null, '["友達","反達","支達","友違"]'::jsonb, 0, '「ともだち」寫作「友達」（也可以寫成「友だち」）。', null, '[{"word":"友達","reading":"ともだち","meaning":"朋友"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-or-006', 'N5', 'vocabulary', 'orthography', 1, '夏は [[あつい]]です。', null, '["熱い","暑い","厚い","悪い"]'::jsonb, 1, '形容天氣「炎熱」用「暑い」。「熱い」用於摸起來燙的東西（熱いお茶），「厚い」是「厚的」。', null, '[{"word":"暑い","reading":"あつい","meaning":"（天氣）熱"},{"word":"熱い","reading":"あつい","meaning":"（東西）燙"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-or-007', 'N5', 'vocabulary', 'orthography', 1, '[[あたらしい]] くつを 買いました。', null, '["親しい","新しい","薪しい","断しい"]'::jsonb, 1, '「あたらしい」寫作「新しい」（新的）。', null, '[{"word":"新しい","reading":"あたらしい","meaning":"新的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-001', 'N5', 'vocabulary', 'contextual', 1, 'ごはんの 前に 手を（　　）。', null, '["あけます","あらいます","ひきます","つけます"]'::jsonb, 1, '「手を洗います」是固定搭配，意思是「洗手」。', null, '[{"word":"洗う","reading":"あらう","meaning":"洗"},{"word":"手","reading":"て","meaning":"手"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-002', 'N5', 'vocabulary', 'contextual', 1, '暑いですから、まどを（　　）。', null, '["しめます","けします","あけます","つけます"]'::jsonb, 2, '因為很熱，所以「開窗」→「まどを あけます」。「しめます」是關上。', null, '[{"word":"開ける","reading":"あける","meaning":"打開"},{"word":"閉める","reading":"しめる","meaning":"關上"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-003', 'N5', 'vocabulary', 'contextual', 1, 'この かばんは（　　）ですから、子どもも 持てます。', null, '["おもい","かるい","ふるい","ひろい"]'::jsonb, 1, '連小孩都拿得動，表示包包「很輕」→「かるい」。', null, '[{"word":"軽い","reading":"かるい","meaning":"輕的"},{"word":"重い","reading":"おもい","meaning":"重的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-004', 'N5', 'vocabulary', 'contextual', 1, '父は 毎晩（　　）を 見ながら ビールを 飲みます。', null, '["ペン","テレビ","ドア","シャツ"]'::jsonb, 1, '可以「看」的東西是「テレビ」（電視）。', null, '[{"word":"毎晩","reading":"まいばん","meaning":"每晚"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-005', 'N5', 'vocabulary', 'contextual', 1, 'この 店は（　　）ので、よく 買い物に 行きます。', null, '["たかい","ながい","やすい","せまい"]'::jsonb, 2, '因為常去買東西，所以店裡的東西「便宜」→「やすい」。', null, '[{"word":"安い","reading":"やすい","meaning":"便宜的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-006', 'N5', 'vocabulary', 'contextual', 1, '電気が 消えて、へやが（　　）なりました。', null, '["あかるく","くらく","しずかに","きれいに"]'::jsonb, 1, '燈熄了，房間變「暗」→「くらく なりました」。形容詞「い」結尾，改成「く」再接「なります」。', null, '[{"word":"暗い","reading":"くらい","meaning":"暗的"}]'::jsonb, '[{"pattern":"い形容詞＋く＋なる","meaning":"變得…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-007', 'N5', 'vocabulary', 'contextual', 1, 'ここで 写真を（　　）ないで ください。', null, '["とら","のま","あび","きか"]'::jsonb, 0, '「写真を撮る」是固定搭配。否定請求「撮らないで ください」＝請不要拍照。', null, '[{"word":"撮る","reading":"とる","meaning":"拍（照）"}]'::jsonb, '[{"pattern":"V ないで ください","meaning":"請不要…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-008', 'N5', 'vocabulary', 'contextual', 1, 'この 川は（　　）ですから、およいでは いけません。', null, '["おいしい","あぶない","あたらしい","うれしい"]'::jsonb, 1, '不可以游泳的理由是「危險」→「あぶない」。', null, '[{"word":"危ない","reading":"あぶない","meaning":"危險的"},{"word":"泳ぐ","reading":"およぐ","meaning":"游泳"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-cx-009', 'N5', 'vocabulary', 'contextual', 1, 'わたしの へやは（　　）ですから、ベッドと つくえしか ありません。', null, '["ひろい","せまい","ながい","たかい"]'::jsonb, 1, '只放得下床和桌子，表示房間「狹小」→「せまい」。「〜しか＋否定」＝只有。', null, '[{"word":"狭い","reading":"せまい","meaning":"狹窄的"}]'::jsonb, '[{"pattern":"〜しか〜ない","meaning":"只有…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-pa-001', 'N5', 'vocabulary', 'paraphrase', 1, '[[この へやは きれいじゃ ありません。]]', null, '["この へやは ひろいです。","この へやは しずかです。","この へやは きたないです。","この へやは あかるいです。"]'::jsonb, 2, '「きれいじゃ ありません」＝不乾淨，意思與「きたないです」（髒）相同。', null, '[{"word":"汚い","reading":"きたない","meaning":"髒的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-pa-002', 'N5', 'vocabulary', 'paraphrase', 1, '[[ごはんを 食べました。それから、はを みがきました。]]', null, '["ごはんの まえに、はを みがきました。","ごはんの あとで、はを みがきました。","ごはんを 食べないで、はを みがきました。","はを みがいて、ごはんを 食べました。"]'::jsonb, 1, '先吃飯，然後刷牙＝「ごはんの あとで、はを みがきました」。', null, '[]'::jsonb, '[{"pattern":"Nの あとで","meaning":"…之後"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-pa-003', 'N5', 'vocabulary', 'paraphrase', 1, '[[あした 学校は 休みです。]]', null, '["あした 学校で 勉強します。","あした 学校へ 行きます。","あした 学校へ 行きません。","あした 学校は 九時からです。"]'::jsonb, 2, '「休み」是放假，所以明天「不去學校」→「行きません」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-pa-004', 'N5', 'vocabulary', 'paraphrase', 1, '[[この 本は むずかしくないです。]]', null, '["この 本は やさしいです。","この 本は おもしろくないです。","この 本は ふるいです。","この 本は たかいです。"]'::jsonb, 0, '「むずかしくない」（不難）＝「やさしい」（簡單）。', null, '[{"word":"易しい","reading":"やさしい","meaning":"簡單的"},{"word":"難しい","reading":"むずかしい","meaning":"困難的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-pa-005', 'N5', 'vocabulary', 'paraphrase', 1, '[[たなかさんは 毎日 じてんしゃで 会社へ 行きます。]]', null, '["たなかさんは 毎日 じてんしゃを 買って 会社へ 行きます。","たなかさんは 毎日 じてんしゃに のって 会社へ 行きます。","たなかさんは 毎日 じてんしゃの 会社へ 行きます。","たなかさんは 毎日 じてんしゃを 作って 会社へ 行きます。"]'::jsonb, 1, '「じてんしゃで 行きます」＝「じてんしゃに のって 行きます」（騎腳踏車去）。「で」表示交通方式，「のる」的受詞用「に」。', null, '[{"word":"乗る","reading":"のる","meaning":"搭乘、騎"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-gf-001', 'N5', 'grammar', 'grammar_form', 1, 'わたしは 毎日 バス（　　）学校へ 行きます。', null, '["を","で","に","が"]'::jsonb, 1, '表示交通工具、手段用助詞「で」：「バスで 行きます」（搭公車去）。', null, '[]'::jsonb, '[{"pattern":"N（交通工具）で 行く","meaning":"搭乘…去"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-gf-002', 'N5', 'grammar', 'grammar_form', 1, 'あした 友だち（　　）会います。', null, '["を","が","に","で"]'::jsonb, 2, '動詞「会う」的對象用助詞「に」：「友だちに 会います」。', null, '[]'::jsonb, '[{"pattern":"Nに 会う","meaning":"見…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-gf-003', 'N5', 'grammar', 'grammar_form', 1, 'A「これは だれ（　　）かばんですか。」B「たなかさんのです。」', null, '["の","を","と","も"]'::jsonb, 0, '表示所屬用「の」：「だれの かばん」（誰的包包）。', null, '[]'::jsonb, '[{"pattern":"N1の N2","meaning":"N1 的 N2"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
