insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-gf-006', 'N5', 'grammar', 'grammar_form', 1, 'きのうは 雨が（　　）、うちに いました。', null, '["ふりましたから","ふって いますから","ふるから","ふりませんから"]'::jsonb, 0, '說的是「昨天」，所以理由用過去式：「ふりましたから」（因為下了雨）。', null, '[]'::jsonb, '[{"pattern":"〜から","meaning":"因為…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
