insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-gf-008', 'N5', 'grammar', 'grammar_form', 1, 'テーブルの 上（　　）りんごが あります。', null, '["で","を","に","と"]'::jsonb, 2, '表示物品存在的場所用「に」：「上に あります」。', null, '[]'::jsonb, '[{"pattern":"Nに Nが ある","meaning":"某處有…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
