insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-sc-001', 'N5', 'grammar', 'sentence_composition', 1, 'あの ＿＿＿ ＿＿＿ ★ ＿＿＿ 山田さんです。', null, '["人は","帽子を","かぶって いる","白い"]'::jsonb, 2, '正確語序：あの 白い 帽子を かぶって いる 人は 山田さんです。★ 的位置是「かぶって いる」。修飾名詞「人」的部分（白い帽子をかぶっている）放在「人は」之前。', null, '[{"word":"帽子","reading":"ぼうし","meaning":"帽子"},{"word":"かぶる","reading":"かぶる","meaning":"戴（帽子）"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n5-sc-002', 'N5', 'grammar', 'sentence_composition', 1, 'つくえの ＿＿＿ ＿＿＿ ★ ＿＿＿ あります。', null, '["三さつ","上に","日本語の","本が"]'::jsonb, 3, '正確語序：つくえの 上に 日本語の 本が 三さつ あります。★ 的位置是「本が」。「日本語の」修飾「本」，數量詞「三さつ」放在「本が」之後。', null, '[{"word":"冊","reading":"さつ","meaning":"（書的量詞）本"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
