insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-pa-002', 'N4', 'vocabulary', 'paraphrase', 2, '[[この スープは ぬるいです。]]', null, '["この スープは とても つめたいです。","この スープは あまり あつく ありません。","この スープは とても あついです。","この スープは あまり おいしく ありません。"]'::jsonb, 1, '「ぬるい」是「微溫、不太熱」，所以是「あまり あつく ありません」。', null, '[{"word":"ぬるい","reading":"ぬるい","meaning":"微溫的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
