insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-pa-004', 'N4', 'vocabulary', 'paraphrase', 2, '[[ここは 禁煙です。]]', null, '["ここでは たばこを 買えません。","ここでは たばこを すっては いけません。","ここは たばこの 店です。","ここでは たばこを すいます。"]'::jsonb, 1, '「禁煙」是禁止吸菸，意思是「たばこを すっては いけません」。', null, '[{"word":"禁煙","reading":"きんえん","meaning":"禁菸"},{"word":"吸う","reading":"すう","meaning":"吸"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-pa-005', 'N4', 'vocabulary', 'paraphrase', 2, '[[ご両親は 留守です。]]', null, '["ご両親は うちに います。","ご両親は ねて います。","ご両親は うちに いません。","ご両親は 働いて います。"]'::jsonb, 2, '「留守」是「不在家」，所以是「うちに いません」。', null, '[{"word":"留守","reading":"るす","meaning":"不在家"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-us-001', 'N4', 'vocabulary', 'usage', 2, '[[さびしい]]', null, '["この スープは さびしくて おいしいです。","さびしい 荷物を 運びます。","あしたの 試験が さびしいです。","友だちが 国へ 帰って、さびしく なりました。"]'::jsonb, 3, '「さびしい」是「寂寞、孤單」的心情。朋友回國後覺得孤單，用法正確。', null, '[{"word":"寂しい","reading":"さびしい","meaning":"寂寞的"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-us-002', 'N4', 'vocabulary', 'usage', 2, '[[ずっと]]', null, '["あした ずっと 学校へ 行きました。","子どもの ときから ずっと この 町に 住んで います。","来週 ずっと 会いましょう。","ずっと 友だちに 会いましたか。"]'::jsonb, 1, '「ずっと」表示狀態或動作長時間持續。「子どもの ときから ずっと 住んで います」是正確用法。', null, '[{"word":"ずっと","reading":"ずっと","meaning":"一直"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-us-003', 'N4', 'vocabulary', 'usage', 2, '[[まじめ]]', null, '["この 料理は まじめです。","まじめな 天気です。","山田さんは まじめな 学生で、宿題を 忘れた ことが ありません。","電車が まじめに 来ました。"]'::jsonb, 2, '「まじめ」形容人認真、踏實。用來形容學生的態度最恰當。', null, '[{"word":"真面目","reading":"まじめ","meaning":"認真"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-us-004', 'N4', 'vocabulary', 'usage', 2, '[[続ける]]', null, '["疲れましたが、もう 少し 勉強を 続けます。","ドアを 続けて ください。","この 荷物を 続けて ください。","電車の 切符を 続けました。"]'::jsonb, 0, '「続ける」是「繼續做某件事」，「勉強を 続ける」（繼續讀書）是正確用法。', null, '[{"word":"続ける","reading":"つづける","meaning":"繼續"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-us-005', 'N4', 'vocabulary', 'usage', 2, '[[ていねい]]', null, '["ていねいな 天気ですね。","電車が ていねいに 来ました。","ていねいな 犬が 好きです。","店の 人は ていねいに 説明して くれました。"]'::jsonb, 3, '「ていねい」形容態度或做事細心、有禮貌。「ていねいに 説明する」是正確用法。', null, '[{"word":"丁寧","reading":"ていねい","meaning":"客氣、仔細"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-001', 'N4', 'grammar', 'grammar_form', 2, '春に（　　）、花が さきます。', null, '["なると","なっても","なったのに","なるのに"]'::jsonb, 0, '表示「一定會發生的自然現象」用「V辭書形＋と」：「春に なると 花が さく」（一到春天，花就開）。', null, '[]'::jsonb, '[{"pattern":"Vと","meaning":"一…就…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-002', 'N4', 'grammar', 'grammar_form', 2, 'わたしは 先生に 名前を（　　）。', null, '["よびました","よばれました","よませました","よめました"]'::jsonb, 1, '被老師叫名字，要用被動形：「よばれました」。', null, '[]'::jsonb, '[{"pattern":"受身形","meaning":"被…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-003', 'N4', 'grammar', 'grammar_form', 2, '母は 子どもに 野菜を（　　）。', null, '["食べさせられました","食べました","食べさせました","食べられました"]'::jsonb, 2, '媽媽讓小孩吃蔬菜，用使役形：「食べさせました」。「食べさせられました」是被迫吃（使役被動），主語不符。', null, '[]'::jsonb, '[{"pattern":"使役形","meaning":"讓…做"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-004', 'N4', 'grammar', 'grammar_form', 2, '雲が 出て きました。もうすぐ 雨が（　　）。', null, '["ふりそうで","ふりそうに","ふりそうです","ふりそうの"]'::jsonb, 2, '根據眼前狀況推測「看起來快要…」用「V ます形去ます＋そうだ」：「ふりそうです」。', null, '[]'::jsonb, '[{"pattern":"Vそうだ","meaning":"看起來快要…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-005', 'N4', 'grammar', 'grammar_form', 2, '日本の 会社で（　　）ために、日本語を 勉強して います。', null, '["はたらいて","はたらく","はたらいた","はたらかない"]'::jsonb, 1, '表示目的用「V辭書形＋ために」：「はたらく ために」。', null, '[]'::jsonb, '[{"pattern":"Vるために","meaning":"為了…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-006', 'N4', 'grammar', 'grammar_form', 2, 'あした 早く（　　）ように、今日は 早く ねます。', null, '["おきた","おきて","おきます","おきる"]'::jsonb, 3, '表示目的、期望的結果用「V辭書形＋ように」：「おきる ように」。', null, '[]'::jsonb, '[{"pattern":"Vるように","meaning":"為了能夠…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-007', 'N4', 'grammar', 'grammar_form', 2, '大切な 本を なくして（　　）。', null, '["おきました","しまいました","ありました","みました"]'::jsonb, 1, '表示遺憾、不小心做了某事用「Vて しまう」：「なくして しまいました」（弄丟了）。', null, '[]'::jsonb, '[{"pattern":"Vて しまう","meaning":"…了（遺憾）；做完"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-008', 'N4', 'grammar', 'grammar_form', 2, 'パーティーの 前に 飲み物を 買って（　　）。', null, '["みえます","おきます","ほしいです","なります"]'::jsonb, 1, '表示事先做好準備用「Vて おく」：「買って おきます」（先買好）。', null, '[]'::jsonb, '[{"pattern":"Vて おく","meaning":"事先…好"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-009', 'N4', 'grammar', 'grammar_form', 2, 'わたしは 一度 富士山に（　　）ことが あります。', null, '["のぼる","のぼった","のぼって","のぼり"]'::jsonb, 1, '表示經驗用「V た形＋ことが ある」：「のぼった ことが あります」（爬過）。', null, '[]'::jsonb, '[{"pattern":"Vた ことが ある","meaning":"曾經…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-010', 'N4', 'grammar', 'grammar_form', 2, '音楽を（　　）、勉強します。', null, '["きいたり","ききながら","きくので","きいても"]'::jsonb, 1, '同時進行兩個動作用「V ます形去ます＋ながら」：「ききながら」。', null, '[]'::jsonb, '[{"pattern":"Vながら","meaning":"一邊…一邊…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-011', 'N4', 'grammar', 'grammar_form', 2, 'きのうは 食べ（　　）て、おなかが いたいです。', null, '["すぎる","すぎれば","すぎ","すぎた"]'::jsonb, 2, '「V ます形去ます＋すぎる」表示過度。接「て」時變成「すぎて」，所以填「すぎ」。', null, '[]'::jsonb, '[{"pattern":"Vすぎる","meaning":"…過頭"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-012', 'N4', 'grammar', 'grammar_form', 2, 'この ペンは 書き（　　）です。', null, '["やすく","やすいで","やすい","やすだ"]'::jsonb, 2, '「V ます形去ます＋やすい」表示容易做某事：「書きやすい」＋「です」。', null, '[]'::jsonb, '[{"pattern":"Vやすい","meaning":"容易…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-013', 'N4', 'grammar', 'grammar_form', 2, 'わたしは 友だちに 宿題を 手伝って（　　）。', null, '["くれました","あげました","もらいました","やりました"]'::jsonb, 2, '「友だちに〜て もらいました」表示接受朋友的幫忙。主語是「わたし」，對方用「に」→「もらう」。若用「くれる」，對方要用「が」。', null, '[]'::jsonb, '[{"pattern":"Vて もらう","meaning":"請（別人）為我…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-014', 'N4', 'grammar', 'grammar_form', 2, 'あした 試験が あるので、今日は 勉強し（　　）。', null, '["なくてもいいです","なければなりません","ないでください","たくありません"]'::jsonb, 1, '明天有考試，所以今天「不得不讀書」→「しなければ なりません」。', null, '[]'::jsonb, '[{"pattern":"Vなければ ならない","meaning":"必須…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-015', 'N4', 'grammar', 'grammar_form', 2, 'わたしは 来年 日本へ 留学する（　　）です。', null, '["はず","よう","つもり","ため"]'::jsonb, 2, '說明自己的打算用「V辭書形＋つもりだ」。「はず」是客觀推測，不用於自己的計畫。', null, '[]'::jsonb, '[{"pattern":"Vるつもりだ","meaning":"打算…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-gf-016', 'N4', 'grammar', 'grammar_form', 2, '来月から 毎日 運動する（　　）しました。', null, '["ために","ことに","ばかりに","ものに"]'::jsonb, 1, '表示自己決定做某事用「V辭書形＋ことに する」：「運動する ことに しました」（決定每天運動）。', null, '[]'::jsonb, '[{"pattern":"Vることに する","meaning":"決定…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-sc-001', 'N4', 'grammar', 'sentence_composition', 2, '子どもの とき、母に きらいな ＿＿＿ ＿＿＿ ★ ＿＿＿。', null, '["ました","野菜を","られ","食べさせ"]'::jsonb, 2, '正確語序：子どもの とき、母に きらいな 野菜を 食べさせ られ ました。★ 的位置是「られ」。「食べさせ＋られ＋ました」是使役被動（被迫吃）的活用順序。', null, '[]'::jsonb, '[{"pattern":"使役受身","meaning":"被迫…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-sc-002', 'N4', 'grammar', 'sentence_composition', 2, '電車が ＿＿＿ ＿＿＿ ★ ＿＿＿ 遅れました。', null, '["ので","事故で","しまった","止まって"]'::jsonb, 2, '正確語序：電車が 事故で 止まって しまった ので 遅れました。★ 的位置是「しまった」。「Vて しまう」＋表示原因的「ので」。', null, '[]'::jsonb, '[{"pattern":"Vて しまう","meaning":"…了（遺憾）"},{"pattern":"〜ので","meaning":"因為…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-sc-003', 'N4', 'grammar', 'sentence_composition', 2, 'お風呂に ＿＿＿ ＿＿＿ ★ ＿＿＿ きました。', null, '["電話が","間に","かかって","入って いる"]'::jsonb, 0, '正確語序：お風呂に 入って いる 間に 電話が かかって きました。★ 的位置是「電話が」。「V ている 間に」表示在…的期間。', null, '[]'::jsonb, '[{"pattern":"Vている 間に","meaning":"在…期間"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-sc-004', 'N4', 'grammar', 'sentence_composition', 2, 'わたしの 趣味は ＿＿＿ ＿＿＿ ★ ＿＿＿ です。', null, '["写真を","こと","古い","集める"]'::jsonb, 3, '正確語序：わたしの 趣味は 古い 写真を 集める ことです。★ 的位置是「集める」。「V辭書形＋こと」把動詞名詞化。', null, '[]'::jsonb, '[{"pattern":"Vること","meaning":"做…這件事"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-sc-005', 'N4', 'grammar', 'sentence_composition', 2, 'あそこに ＿＿＿ ＿＿＿ ★ ＿＿＿ います。', null, '["男の 子が","着て いる","青い","シャツを"]'::jsonb, 1, '正確語序：あそこに 青い シャツを 着て いる 男の 子が います。★ 的位置是「着て いる」。修飾「男の 子」的部分（青いシャツを着ている）要放在「男の 子が」之前。', null, '[{"word":"着る","reading":"きる","meaning":"穿"}]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-001', 'N4', 'grammar', 'text_grammar', 2, '（１）', 'n4-ps-001', '["しかし","だから","それで","たとえば"]'::jsonb, 0, '前文說搬家前擔心交不到朋友，後文說大阪人很親切，是轉折關係，所以用「しかし」（但是）。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-002', 'N4', 'grammar', 'text_grammar', 2, '（２）', 'n4-ps-001', '["くれました","あげました","もらいました","いただきました"]'::jsonb, 0, '「知らない 人が 〜て くれました」：別人（主語）為我做了某事。「もらう／いただく」的主語是接受者，且對方要用「に」。', null, '[]'::jsonb, '[{"pattern":"Vて くれる","meaning":"（別人）為我…"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-003', 'N4', 'grammar', 'text_grammar', 2, '（３）', 'n4-ps-001', '["それでは","だから","しかし","また"]'::jsonb, 3, '前面舉了「問路時有人幫忙」的例子，後面再舉「超市店員打招呼」的例子，是追加的關係，用「また」（還有）。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-004', 'N4', 'grammar', 'text_grammar', 2, '（４）', 'n4-ps-001', '["ですから","ですが","ですので","でして"]'::jsonb, 1, '「朋友還很少」與「每天過得很開心」是轉折關係，用「ですが」：「少ないですが、〜」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-005', 'N4', 'grammar', 'text_grammar', 2, '（１）', 'n4-ps-002', '["でも","ですから","たとえば","ところが"]'::jsonb, 1, '走路要四十分鐘，所以必須每天六點起床，前後是因果關係，用「ですから」（因此）。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-006', 'N4', 'grammar', 'text_grammar', 2, '（２）', 'n4-ps-002', '["が","から","ので","ために"]'::jsonb, 0, '「最初は 大変でした」與「今は 楽しみに なりました」形成對比，用「が」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-007', 'N4', 'grammar', 'text_grammar', 2, '（３）', 'n4-ps-002', '["しかし","ところで","それに","だから"]'::jsonb, 2, '前一句說可以看到季節的花，後一句再補充「天氣好時空氣也很舒服」，是追加優點，用「それに」（而且）。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-tg-008', 'N4', 'grammar', 'text_grammar', 2, '（４）', 'n4-ps-002', '["まだ","たぶん","もし","ぜひ"]'::jsonb, 3, '向讀者推薦、邀請時用「ぜひ」（務必、一定要），與「〜て みては いかがですか」搭配自然。', null, '[]'::jsonb, '[{"pattern":"ぜひ","meaning":"務必、一定"}]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rn-001', 'N4', 'reading', 'reading_notice', 2, '飲み会に ついて、正しい ものは どれですか。', 'n4-ps-003', '["場所は 変わったが、時間は 同じだ。","時間は 変わったが、場所は 同じだ。","場所も 時間も 変わった。","場所も 時間も 変わらない。"]'::jsonb, 0, '信中說場所從「さくら」改成「はなみ」，但「時間は 同じ 六時です」，時間沒變。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rn-002', 'N4', 'reading', 'reading_notice', 2, 'もえる ごみは いつ 出しますか。', 'n4-ps-004', '["月曜日と 水曜日の 朝","月曜日と 木曜日の 朝 八時までに","水曜日の 夜","毎日 朝 八時まで"]'::jsonb, 1, '可燃垃圾是星期一和星期四，早上八點前要拿出來。星期三是瓶罐。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rl-001', 'N4', 'reading', 'reading_life', 2, '『わたし』は 先週 借りた 本に ついて、どう 思って いますか。', 'n4-ps-005', '["もう ぜんぶ 読んだ","来週 返す までに ぜんぶ 読みたい","読む つもりは ない","もう 一度 借りたい"]'::jsonb, 1, '目前只讀了一本，並說「来週 返す までに ぜんぶ 読みたい」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rs-001', 'N4', 'reading', 'reading_short', 2, '子どもは ケーキを いつ 食べても いいですか。', 'n4-ps-006', '["すぐ 食べても いい","夕ごはんの あとで 食べる","お母さんが 帰る 前に 食べる","食べては いけない"]'::jsonb, 1, '媽媽說「夕ごはんの 前には 食べないで」，所以晚餐之後才可以吃。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rn-003', 'N4', 'reading', 'reading_notice', 2, 'スミスさんは レストランに ついて どう 思って いますか。', 'n4-ps-007', '["料理は よかったが、店の 人は 親切ではなかった","料理も 店の 人も よかった","料理は 高かったが、おいしかった","もう 行きたく ない"]'::jsonb, 1, '信中說「料理も おいしかったし、店の 人も 親切でした。また 行きたいです」，料理與服務都很好。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rm-001', 'N4', 'reading', 'reading_mid', 2, '『わたし』は どうして 自転車を 買いましたか。', 'n4-ps-008', '["バスの 本数が 少ないから","運動が したかったから","歩くのが きらいだから","雨の 日にも 使えるから"]'::jsonb, 0, '文中「バスも ありますが、本数が 少なくて…それで、去年 自転車を 買いました」，原因是公車班次少。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rm-002', 'N4', 'reading', 'reading_mid', 2, '自転車に ついて、この 文章の 内容と 合って いる ものは どれですか。', 'n4-ps-008', '["雨の 日も 便利だ","駅の 近くは おく 場所が 少ない","駅まで バスより 時間が かかる","運動には ならない"]'::jsonb, 1, '最後一句說「駅の 近くに 自転車を おく 場所が 少なくて…大変です」。下雨天不能騎，且對運動有幫助。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rm-003', 'N4', 'reading', 'reading_mid', 2, 'ケンさんは どうして 図書館で 復習しますか。', 'n4-ps-009', '["家だと ゲームを して しまうから","先生に 図書館で するように 言われたから","家に 辞書が ないから","図書館の ほうが 学校より 近いから"]'::jsonb, 0, '文中「家では ゲームを して しまいます。それで、図書館で 勉強する ことに しました」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rm-004', 'N4', 'reading', 'reading_mid', 2, '先生は 復習に ついて 何と 言いましたか。', 'n4-ps-009', '["週末に まとめて した ほうが いい","毎日 二時間 した ほうが いい","その 日の うちに した ほうが いい","図書館で した ほうが いい"]'::jsonb, 2, '先生說「復習は その 日の うちに した ほうが いい」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rm-005', 'N4', 'reading', 'reading_mid', 2, '先週、『わたし』は どうして 火曜日に 買い物に 行けませんでしたか。', 'n4-ps-010', '["病気だったから","店が 休みだったから","仕事が 長く かかったから","野菜が 高かったから"]'::jsonb, 2, '文中「先週は 仕事が 長引いて、行けませんでした」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rm-006', 'N4', 'reading', 'reading_mid', 2, '今週、『わたし』は どう しますか。', 'n4-ps-010', '["水曜日に 買い物に 行く","スーパーに 行かない","野菜を 買わない","火曜日に 買い物に 行く"]'::jsonb, 3, '最後一句「今週は 必ず 火曜日に 行こうと 思います」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-rm-007', 'N4', 'reading', 'reading_mid', 2, '『わたし』は 今、コーヒーに ついて どう 思って いますか。', 'n4-ps-011', '["砂糖が ない ほうが 好きだ","砂糖が ないと 飲めない","にがくて 好きではない","健康の ために 飲むのを やめた"]'::jsonb, 0, '文中「今は この 味が 好きです」。この味＝砂糖を入れないコーヒーの味。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-ri-001', 'N4', 'reading', 'reading_info', 2, '小学四年生の みきさんは 八月 十二日に 料理教室に 参加したいです。いつまでに 何を しますか。', 'n4-ps-012', '["八月 五日までに 市民センターに 行く","七月 三十一日までに 電話で 申し込む","七月 三十一日までに メールで 申し込む","当日 申し込む"]'::jsonb, 1, '申請方式是「電話で 七月 三十一日までに」。八月十二日是上課日之一，對象是小學生。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-ri-002', 'N4', 'reading', 'reading_info', 2, '参加する 日に 持って 行く ものは どれですか。', 'n4-ps-012', '["エプロンと タオル","材料と タオル","エプロンと 材料","エプロンと タオルと 材料"]'::jsonb, 0, '「持ち物：エプロン、タオル」。材料費已含在費用內，不用自備材料。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
insert into public.questions (id, level, subject, qtype, difficulty, stem, passage_id, options, answer_index, explanation_zh, note_ja, vocab, grammar, source, status) values ('n4-ri-003', 'N4', 'reading', 'reading_info', 2, '朝 九時に 借りて、午後 一時に 返します。いくらですか。', 'n4-ps-013', '["八百円","五百円","六百円","千円"]'::jsonb, 1, '九點到下午一點是四小時，適用「四時間まで 五百円」。', null, '[]'::jsonb, '[]'::jsonb, 'original', 'approved') on conflict (id) do update set stem = excluded.stem, passage_id = excluded.passage_id, options = excluded.options, answer_index = excluded.answer_index, explanation_zh = excluded.explanation_zh, note_ja = excluded.note_ja, vocab = excluded.vocab, grammar = excluded.grammar, difficulty = excluded.difficulty, status = excluded.status;
